package glitch

import data.glitch_lib

# Unencrypted protocols
unencrypted_protocols := {"http", "ftp", "tcp", "udp", "plain", "unencrypted", "raw"}

# Encrypted protocol alternatives
encrypted_alternatives := {"https", "tls", "ssl", "sftp", "ssh", "ftps"}

# Unencrypted default ports
unencrypted_ports := {"80", "21", "23", "25"}

# Integrity-related field names
integrity_fields := {"checksum", "crc", "hash", "mac", "hmac", "integrity_check", "verify_integrity", "validate_payload", "signature", "signed_payload", "content_hash"}

# Encryption/security field names
encryption_fields := {"encryption", "use_tls", "ssl_enabled", "tls_enabled", "verify_ssl", "ssl_verification", "cert_validation"}

# Weak integrity algorithms
weak_algorithms := {"md5", "sha1", "crc32", "none"}

# Boolean flag names indicating disabled security
insecure_flags := {"insecure", "skip_validation", "disable_encryption", "allow_unencrypted", "skip_verify", "insecure_registry", "registry_skip_verify", "insecure_webhook", "allow_http_callbacks", "skip_signature_check", "continue_on_error"}

# SSL/TLS mode fields
ssl_mode_fields := {"sslmode", "ssl_mode", "require_ssl"}

# Risky SSL mode values
risky_ssl_modes := {"disable", "prefer", "false", "none", "disabled"}

# Helper to check if value is a string matching any in set
string_matches_set(value, set) {
    value.ir_type == "String"
    set[lower(value.value)]
} else {
    value.ir_type == "VariableReference"
    set[lower(value.value)]
}

# Helper to check if boolean is true (insecure enabled)
is_true(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    lower(value.value) == "true"
} else {
    value.ir_type == "String"
    lower(value.value) == "enabled"
}

# Helper to check if boolean is false (security disabled)
is_false_or_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower(value.value) == "false"
} else {
    value.ir_type == "String"
    lower(value.value) == "disabled"
} else {
    value.ir_type == "String"
    lower(value.value) == "none"
} else {
    value.ir_type == "String"
    lower(value.value) == "null"
} else {
    value.ir_type == "Null"
}

# Helper to check if value is null/none
is_null_or_none(value) {
    value.ir_type == "Null"
} else {
    value.ir_type == "String"
    lower(value.value) == "none"
} else {
    value.ir_type == "String"
    lower(value.value) == "null"
}

# Check for unencrypted protocol in string value
has_unencrypted_protocol(value) {
    value.ir_type == "String"
    proto := unencrypted_protocols[_]
    contains(lower(value.value), proto)
    # Check not https when http is found
    not (proto == "http" and regex.match("https", lower(value.value)))
}

# Get attribute by name from set
get_attr_by_name(attrs, name_set) = attr {
    attr := attrs[_]
    name_set[lower(attr.name)]
}

# Check if any integrity field exists in attributes
has_integrity_field(attrs) {
    attr := attrs[_]
    integrity_fields[lower(attr.name)]
}

# Check if any encryption field exists in attributes
has_encryption_field(attrs) {
    attr := attrs[_]
    encryption_fields[lower(attr.name)]
}

# Check container image without digest
is_tag_only_image(value) {
    value.ir_type == "String"
    # Has tag (colon) but no digest (@sha256)
    regex.match(".*:.*", value.value)
    not regex.match(".*@sha256.*", value.value)
    not regex.match(".*@.*:.*", value.value)
}

# Check for weak algorithm specification
uses_weak_algorithm(value) {
    value.ir_type == "String"
    weak_algorithms[lower(value.value)]
}

# Pattern 1: Unencrypted protocol usage without integrity check
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for data transfer or communication related atomic units
    pattern_types := {"connection", "transport", "protocol", "endpoint", "url", "uri", "address", "host", "server", "client", "request", "response", "webhook", "callback", "ingress", "egress", "service", "listener"}
    pattern_type := pattern_types[_]
    contains(lower(node.type), pattern_type)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for unencrypted protocol
    protocol_attrs := {"protocol", "scheme", "transport", "method", "type", "url", "uri", "address", "endpoint"}
    protocol_attrs[lower(attr.name)]
    has_unencrypted_protocol(attr.value)

    # Verify no integrity fields present
    not has_integrity_field(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Unencrypted protocol used without integrity verification. (CWE-353)"
    }
}

# Pattern 2: Explicitly disabled encryption or integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for SSL/TLS mode set to unsafe value
    ssl_mode_fields[lower(attr.name)]
    string_matches_set(attr.value, risky_ssl_modes)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - SSL/TLS security explicitly disabled or set to weak mode. (CWE-353)"
    }
}

# Pattern 3: Insecure boolean flags enabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    insecure_flags[lower(attr.name)]
    is_true(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Insecure flag explicitly enabled, bypassing integrity checks. (CWE-353)"
    }
}

# Pattern 4: Security features explicitly disabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check encryption-related fields set to false/disabled/none
    encryption_check_fields := {"encryption", "use_tls", "ssl_enabled", "tls_enabled", "verify_ssl", "ssl_verification", "cert_validation", "checksum_verification", "verify", "strict", "enabled", "active"}
    encryption_check_fields[lower(attr.name)]
    is_false_or_disabled(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Security or integrity verification explicitly disabled. (CWE-353)"
    }
}

# Pattern 5: Integrity fields explicitly set to null/none
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    integrity_fields[lower(attr.name)]
    is_null_or_none(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Integrity check mechanism explicitly set to none. (CWE-353)"
    }
}

# Pattern 6: Weak algorithm for integrity
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    algorithm_fields := {"algorithm", "hash_algorithm", "checksum_algorithm", "digest_algorithm", "signing_algorithm", "mac_algorithm"}
    algorithm_fields[lower(attr.name)]
    uses_weak_algorithm(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Cryptographically weak algorithm used for integrity verification. (CWE-353)"
    }
}

# Pattern 7: Container image without digest verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Container or image related resources
    container_types := {"container", "image", "pod", "deployment", "replicaset", "daemonset", "statefulset", "job", "cronjob"}
    container_type := container_types[_]
    contains(lower(node.type), container_type)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    image_attrs := {"image", "container_image"}
    image_attrs[lower(attr.name)]
    is_tag_only_image(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Container image referenced by tag only without digest for integrity verification. (CWE-353)"
    }
}

# Pattern 8: Unencrypted port without security controls
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    port_types := {"port", "listener_port", "target_port", "container_port", "service_port"}
    port_type := port_types[_]
    contains(lower(node.type), port_type)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    port_attrs := {"port", "target_port", "container_port", "port_number", "number"}
    port_attrs[lower(attr.name)]

    # Check for unencrypted port value
    string_matches_set(attr.value, unencrypted_ports)

    # No TLS/security attribute present
    not has_encryption_field(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Unencrypted default port used without integrity protection. (CWE-353)"
    }
}

# Pattern 9: Data storage without integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
