    storage_types := {"bucket", "object", "storage", "blob", "file", "archive", "artifact", "package", "module", "state"}
    storage_type := storage_types[_]
    contains(lower(node.type), storage_type)

    # No integrity fields present
    attrs := glitch_lib.all_attributes(node)
    not has_integrity_field(attrs)

    # Has content/data attributes suggesting data storage
    data_attrs := {"source", "content", "data", "body", "object", "file", "archive", "artifact"}
    data_attr := attrs[_]
    data_attrs[lower(data_attr.name)]

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Data storage resource lacks integrity verification configuration. (CWE-353)"
    }
}

# Pattern 10: Database connection without SSL/TLS
Glitch_Analysis[result] {
