    db_type := db_types[_]
    contains(lower(node.type), db_type)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for explicit SSL disable
    attr.name == "sslmode"
    string_matches_set(attr.value, risky_ssl_modes)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Database connection with SSL/TLS disabled or set to weak mode. (CWE-353)"
    }
}

# Pattern 11: Remote state or module source without integrity check
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    source_types := {"module", "source", "remote_state", "backend", "provider"}
    source_type := source_types[_]
    contains(lower(node.type), source_type)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Has source/location attribute
    source_attrs := {"source", "location", "url", "git", "http", "https"}
    source_attrs[lower(attr.name)]

    attr.value.ir_type == "String"
    # Contains http or git without integrity verification
    regex.match("^(http|git|ftp)://", lower(attr.value.value))

    # No integrity verification present
    not has_integrity_field(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Remote source without integrity verification mechanism. (CWE-353)"
    }
}

